import{_ as a,o as t,c as s,a3 as i}from"./chunks/framework.CVt6dz2a.js";const u=JSON.parse('{"title":"EP.07 纹理 UV 与流动","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.07-texture-uv.md","filePath":"comics/EP.07-texture-uv.md","lastUpdated":1792595797000}'),r={name:"comics/EP.07-texture-uv.md"};function o(l,e,n,d,p,h){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="ep-07-纹理-uv-与流动" tabindex="-1">EP.07 纹理 UV 与流动 <a class="header-anchor" href="#ep-07-纹理-uv-与流动" aria-label="Permalink to &quot;EP.07 纹理 UV 与流动&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../guide/07-texture/basics">7.1 基础入门：纹理贴图与 CanvasTexture</a> 延伸阅读：<a href="./../guide/07-texture/advanced">进阶篇</a> · <a href="./../guide/07-texture/practice">实战篇</a> 动手演示：<a href="./../public/demos/texture/canvas-texture.html">canvas-texture 程序化贴图</a> · <a href="./../public/demos/texture/wrapping.html">wrapping 环绕与 repeat</a> · <a href="./../public/demos/texture/flowing-texture.html">flowing-texture 赛博流动地板</a></p></blockquote><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><table tabindex="0"><thead><tr><th>格</th><th>场景</th></tr></thead><tbody><tr><td>① 困境</td><td>标签君贴的网格图发暗发灰；设了 <code>repeat.set(4,4)</code> 瓷砖却毫无反应，只有一张被拉伸的大图。</td></tr><tr><td>② 揭秘</td><td>码叔摊开 UV：每个顶点都有 0~1 的纹理坐标，GPU 沿 UV 采样贴图；发暗是色彩空间没标 sRGB，repeat 无效是环绕模式仍是默认 Clamp。</td></tr><tr><td>③ 实证</td><td>像素酱补上 <code>colorSpace = SRGBColorSpace</code> 与 <code>wrapS/wrapT = RepeatWrapping</code>，再逐帧推 <code>texture.offset.x</code>，赛博地板的网格线开始无限流动。</td></tr><tr><td>④ 结案</td><td>码叔总结：颜色贴图标 sRGB、数据贴图保线性；斜看模糊加 anisotropy，Canvas 重绘后 needsUpdate。</td></tr></tbody></table><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="_1-uv-顶点到图片的映射表" tabindex="-1">① UV：顶点到图片的映射表 <a class="header-anchor" href="#_1-uv-顶点到图片的映射表" aria-label="Permalink to &quot;① UV：顶点到图片的映射表&quot;">​</a></h3><p>几何体每个顶点带一组 <code>(u, v)</code>，范围通常 0~1，原点在图片<strong>左下角</strong>。GPU 在三角形内部对 UV 插值，逐像素从贴图读取颜色（采样），把 2D 图片&quot;裹&quot;到 3D 表面。贴图朝向不对时，先怀疑 UV 方向与 <code>texture.flipY</code>。</p><h3 id="_2-发暗-色彩空间必须标对" tabindex="-1">② 发暗：色彩空间必须标对 <a class="header-anchor" href="#_2-发暗-色彩空间必须标对" aria-label="Permalink to &quot;② 发暗：色彩空间必须标对&quot;">​</a></h3><p>r152 起色彩管理默认开启：</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 颜色类贴图：必须标 sRGB，否则经线性转换后发暗发灰</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">texture.colorSpace </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> THREE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.SRGBColorSpace</span></span></code></pre></div><ul><li>颜色类（<code>map</code>、<code>emissiveMap</code>）：设 <strong>SRGBColorSpace</strong>；</li><li>数据类（<code>normalMap</code>、<code>roughnessMap</code>、<code>metalnessMap</code>、<code>aoMap</code>）：保持<strong>线性</strong>，设了反而出错。</li></ul><h3 id="_3-repeat-无效-先改环绕模式" tabindex="-1">③ repeat 无效：先改环绕模式 <a class="header-anchor" href="#_3-repeat-无效-先改环绕模式" aria-label="Permalink to &quot;③ repeat 无效：先改环绕模式&quot;">​</a></h3><p>Texture 默认是 ClampToEdgeWrapping（超出 0~1 的 UV 反复采样边缘像素）。想要瓷砖效果：</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">texture.wrapS </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> THREE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.RepeatWrapping</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">texture.wrapT </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> THREE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.RepeatWrapping</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">texture.repeat.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">set</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>其它模式：MirroredRepeatWrapping（镜像平铺，接缝更隐蔽）；ClampToEdgeWrapping（默认，适合 UI/光照贴图）。</p><h3 id="_4-流动贴图与清晰度" tabindex="-1">④ 流动贴图与清晰度 <a class="header-anchor" href="#_4-流动贴图与清晰度" aria-label="Permalink to &quot;④ 流动贴图与清晰度&quot;">​</a></h3><ul><li>流动：每帧 <code>texture.offset.x += speed * dt</code>，配合 Repeat 实现无限滚动（传送带、赛博地板、流水）；</li><li>斜视摩尔纹/糊：提高 <code>texture.anisotropy</code>（上限 <code>renderer.capabilities.getMaxAnisotropy()</code>）；</li><li>程序化纹理零资源方案：<code>&lt;canvas&gt;</code> 画图 → <code>new THREE.CanvasTexture(canvas)</code>，重绘 canvas 后必须 <code>texture.needsUpdate = true</code> 才会重新上传。</li></ul><h2 id="坑点清单-faq" tabindex="-1">坑点清单（FAQ） <a class="header-anchor" href="#坑点清单-faq" aria-label="Permalink to &quot;坑点清单（FAQ）&quot;">​</a></h2><ul><li><strong>Q：法线贴图也设了 sRGB，凹凸感怪怪的？</strong> normalMap 是数据不是颜色，必须保持线性空间。</li><li><strong>Q：repeat 设了 2×2 还是只显示一次？</strong> 确认 wrapS/wrapT 都改成 RepeatWrapping；Clamp 模式下 repeat 大于 1 没有平铺效果。</li><li><strong>Q：CanvasTexture 动态重绘后画面不更新？</strong> 触发 <code>texture.needsUpdate = true</code>；频繁整图重绘有开销，只在内容真正变化时设置。</li><li><strong>Q：贴图上下颠倒？</strong> Three.js 默认 <code>flipY = true</code> 以匹配图片左上角原点的约定；与自定义 UV/数据纹理不匹配时手动切换。</li><li><strong>Q：地面远处网格闪烁？</strong> 共面 z-fighting 时用 polygonOffset 拉开层级，并参考 EP.03 收紧 near/far。</li></ul><h2 id="自测-quiz" tabindex="-1">自测（Quiz） <a class="header-anchor" href="#自测-quiz" aria-label="Permalink to &quot;自测（Quiz）&quot;">​</a></h2><ol><li>颜色贴图发暗，应该设置哪个属性？法线贴图也要设吗？</li><li><code>texture.repeat.set(4,4)</code> 不生效，还缺哪两个设置？</li><li>想让地面网格每帧向前流动，逐帧修改纹理的哪个属性？为什么不用移动几何体？</li></ol><details><summary>答案</summary><ol><li>设置 <strong><code>texture.colorSpace = THREE.SRGBColorSpace</code></strong>；法线贴图<strong>不要设</strong>，它是线性数据类贴图，设 sRGB 会导致凹凸计算错误。</li><li><strong><code>wrapS = THREE.RepeatWrapping</code></strong> 与 <strong><code>wrapT = THREE.RepeatWrapping</code></strong>；默认的 ClampToEdge 会忽略 0~1 之外的重复采样。</li><li>修改 <strong><code>texture.offset</code></strong>（如 <code>offset.y += speed * dt</code>）。偏移只改采样坐标、成本极低；移动几何体则要持续重建/平移顶点或网格，开销大且不适合无限平铺。</li></ol></details>`,22)])])}const g=a(r,[["render",o]]);export{u as __pageData,g as default};
